const R = (name, label, fields, extra = {}) => ({ name, label, type: 'repeater', fields, ...extra });
const T = (name, label, type = 'text', extra = {}) => ({ name, label, type, ...extra });
/* Layout controls for any card section on the home page: grid or carousel, columns, auto slide, seconds. */
const LAYOUT = (k, what) => [
  T(`${k}.layout`, 'Layout', 'segmented', { half: true, options: [{ value: 'grid', label: 'Grid' }, { value: 'carousel', label: 'Carousel' }], info: `Grid shows every ${what} at once. Carousel shows a row visitors can slide.` }),
  T(`${k}.columns`, 'Cards per row', 'segmented', { half: true, options: [{ value: '2', label: '2' }, { value: '3', label: '3' }, { value: '4', label: '4' }], info: 'How many cards sit side by side on a wide screen. Phones always show one.' }),
  T(`${k}.autoplay`, 'Slide automatically (carousel)', 'switch', { half: true, info: 'On: the carousel moves by itself and pauses when the mouse is over it. Off: visitors slide with the arrows, the dots or a swipe.' }),
  T(`${k}.interval`, 'Seconds between slides', 'number', { half: true, info: 'How long each slide stays. Between 2 and 30 seconds. Empty uses 5.' }),
];

